from tempfile import NamedTemporaryFile
from typing import Optional, Sequence
from pydantic import BaseModel, FilePath

class TemporaryFileManager:
    def __init__(self):
        self.temp_files = []

    def add_temp_file(self, content: str) -> str:
        with NamedTemporaryFile(mode='w', delete=False) as temp_file:
            temp_file.write(content)
            self.temp_files.append(temp_file.name)
            return temp_file.name

    def remove_temp_file(self, file_path: str) -> None:
        if file_path in self.temp_files:
            self.temp_files.remove(file_path)
            # Remove the file from the filesystem
            import os
            os.remove(file_path)

    def list_temp_files(self) -> Sequence[str]:
        return self.temp_files

    def get_temp_file_content(self, file_path: str) -> Optional[str]:
        if file_path in self.temp_files:
            with open(file_path, 'r') as file:
                return file.read()
        return None
```

This solution provides a `TemporaryFileManager` class that manages temporary files, allowing the addition, removal, listing, and retrieval of file content. The class uses `NamedTemporaryFile` to create temporary files and maintains a list of file paths for management. The methods perform the required operations while handling input validation and error cases.

