def caesar_cipher(input_string, shift):
    result = ""
    for char in input_string:
        if char.isalpha():
            shift_amount = shift % 26  # Ensure shift is within one full rotation of the alphabet
            if char.islower():
                shifted_char = chr(((ord(char) - ord('a') + shift_amount) % 26) + ord('a'))
            else:
                shifted_char = chr(((ord(char) - ord('A') + shift_amount) % 26) + ord('A'))
            result += shifted_char
        else:
            result += char
    return result
