class ConfigurationManager:
    def __init__(self, vault, consul, consul_prefix):
        self.vault = vault
        self.consul = consul
        self.consul_prefix = consul_prefix

    def write_configuration(self, configuration, org_slug, project_slug, app_slug, version):
        if configuration.buildtime:
            self.vault.vault_connection.write(
                f'{self.consul_prefix}/{org_slug}/{project_slug}-{app_slug}/configuration/'
                f'{configuration.name}/{version}/{configuration.name}',
                **{configuration.name: configuration.value},
            )
        else:
            if self.consul is None:
                raise RuntimeError('No Consul extension configured!')
            config_key_name = (f'{self.consul_prefix}'
                               f'/{org_slug}/{project_slug}-{app_slug}/configuration/'
                               f'{configuration.name}/{version}/{configuration.name}')
            self.consul.write(config_key_name, configuration.value)

    def read_configuration(self, configuration, org_slug, project_slug, app_slug, version):
        if configuration.buildtime:
            return self.vault.vault_connection.read(
                f'{self.consul_prefix}/{org_slug}/{project_slug}-{app_slug}/configuration/'
                f'{configuration.name}/{version}/{configuration.name}'
            )
        else:
            if self.consul is None:
                raise RuntimeError('No Consul extension configured!')
            config_key_name = (f'{self.consul_prefix}'
                               f'/{org_slug}/{project_slug}-{app_slug}/configuration/'
                               f'{configuration.name}/{version}/{configuration.name}')
            return self.consul.read(config_key_name)
```
In the `ConfigurationManager` class, the `write_configuration` method writes the configuration value to either the vault or Consul based on the build time, and the `read_configuration` method reads the configuration value from either the vault or Consul based on the build time. The appropriate keys are constructed based on the provided organization slug, project slug, app slug, version, and configuration name. If the Consul extension is not configured when attempting to write or read from Consul, a `RuntimeError` is raised.

