class KoNLPyWordPieceTokenizer:
    def __init__(self, konlpy_instance, use_tag=False):
        self.konlpy_instance = konlpy_instance
        self.use_tag = use_tag

    def tokenize(self, text):
        if self.use_tag:
            tokens = self.konlpy_instance.pos(text)
            tokens = [token for token, tag in tokens]
        else:
            tokens = self.konlpy_instance.morphs(text)
        return tokens

class KoNLPyBertTokenizer:
    def __init__(self, konlpy_wordpiece, vocab_file):
        self.konlpy_wordpiece = konlpy_wordpiece
        self.vocab_file = vocab_file

    def tokenize(self, text):
        word_pieces = self.konlpy_wordpiece.tokenize(text)
        return word_pieces

def get_tokenizer(vocab_file, konlpy_name, use_tag=False):
    KONLPY = {
        'mecab': Mecab,
        'komoran': Komoran,
        'okt': Okt,
        'hannanum': Hannanum
    }
    if konlpy_name not in KONLPY:
        raise ValueError(f'Support only {set(KONLPY.keys())}')
    konlpy_bert_tokenizer = KoNLPyBertTokenizer(
        konlpy_wordpiece=KoNLPyWordPieceTokenizer(KONLPY[konlpy_name](), use_tag=use_tag),
        vocab_file=vocab_file
    )
    return konlpy_bert_tokenizer
```

