import collections

class FPS:
    def __init__(self, averageof=50):
        self.frametimestamps = collections.deque(maxlen=averageof)

    def __call__(self):
        self.frametimestamps.append(time.time())
        if len(self.frametimestamps) > 1:
            fps = len(self.frametimestamps) / (self.frametimestamps[-1] - self.frametimestamps[0])
            return fps
        else:
            # Handle the case when there are not enough frame timestamps
            return 0  # Return 0 FPS when there are not enough frame timestamps
```

