def is_scope_correct_if_delimiter_not_at_bol(input_string: str) -> bool:
    stack = []
    for char in input_string:
        if char == '$':
            stack.append('$')
        elif char == '@':
            if stack and stack[-1] == '$':
                stack.pop()
            else:
                return False
        elif char == '"':
            if stack and stack[-1] == '@':
                stack.pop()
            else:
                return False
    return len(stack) == 0
```
