class Page:
    def __init__(self, items, page_number):
        self.items = items
        self.page_number = page_number

    def get_items(self):
        page_size = 10
        start_index = (self.page_number - 1) * page_size
        end_index = start_index + page_size
        return self.items[start_index:end_index]

    def has_next_page(self):
        return self.page_number * 10 < len(self.items)

    def has_previous_page(self):
        return self.page_number > 1


class PageQuery:
    def __init__(self, items, page_size):
        self.items = items
        self.page_size = page_size

    def get_page(self, page_number):
        return Page(self.items, page_number)

    def get_total_pages(self):
        return (len(self.items) + self.page_size - 1) // self.page_size
```

