class BankAccount:
    def __init__(self, account_number, initial_balance):
        self.account_number = account_number
        self.balance = initial_balance

    def deposit(self, amount):
        """Add the given amount to the account balance."""
        self.balance += amount

    def withdraw(self, amount):
        """Deduct the given amount from the account balance if sufficient funds are available."""
        if amount <= self.balance:
            self.balance -= amount
        else:
            print("Insufficient funds")

    def check_balance(self):
        """Return the current balance of the account."""
        return self.balance


class TransferableBankAccount(BankAccount):
    def __init__(self, account_number, initial_balance):
        super().__init__(account_number, initial_balance)

    def transfer_funds(self, recipient_account, amount):
        """Transfer the given amount from this account to the recipient account."""
        if amount <= self.balance:
            self.balance -= amount
            recipient_account.deposit(amount)
        else:
            print("Insufficient funds for transfer")
