class CustomPriorityQueue:
    def __init__(self):
        self.queue = []

    def put(self, item, priority):
        self.queue.append((item, priority))
        self._sift_up(len(self.queue) - 1)

    def get(self):
        if not self.queue:
            raise IndexError("get from an empty priority queue")
        self._swap(0, len(self.queue) - 1)
        item, _ = self.queue.pop()
        self._sift_down(0)
        return item

    def empty(self):
        return not self.queue

    def _sift_up(self, index):
        while index > 0:
            parent = (index - 1) // 2
            if self.queue[parent][1] > self.queue[index][1]:
                self._swap(parent, index)
                index = parent
            else:
                break

    def _sift_down(self, index):
        size = len(self.queue)
        while index < size:
            left_child = 2 * index + 1
            right_child = 2 * index + 2
            min_index = index
            if left_child < size and self.queue[left_child][1] < self.queue[min_index][1]:
                min_index = left_child
            if right_child < size and self.queue[right_child][1] < self.queue[min_index][1]:
                min_index = right_child
            if min_index != index:
                self._swap(index, min_index)
                index = min_index
            else:
                break

    def _swap(self, i, j):
        self.queue[i], self.queue[j] = self.queue[j], self.queue[i]
```

