import ast

def extract_package_info(file_path):
    with open(file_path, 'r') as file:
        content = file.read()
        tree = ast.parse(content)
        setup_call = next(node for node in ast.walk(tree) if isinstance(node, ast.Call) and getattr(node.func, 'id', '') == 'setup')
        args = setup_call.args
        kwargs = setup_call.keywords
        package_info = {}
        for arg in args:
            if isinstance(arg, ast.Str):
                package_info['name'] = arg.s
        for kwarg in kwargs:
            if kwarg.arg == 'version' and isinstance(kwarg.value, ast.Str):
                package_info['version'] = kwarg.value.s
        return package_info

