        self.items = items
        self.per_page = per_page
        self.writable = writable
        self.current_page = 1

    def set_items_per_page(self, per_page):
        self.per_page = per_page

    def next_page(self):
        if self.current_page * self.per_page < len(self.items):
            self.current_page += 1

    def prev_page(self):
        if self.current_page > 1:
            self.current_page -= 1

    def update_writable_status(self, writable):
        self.writable = writable

    def display_current_page_items(self):
        start_index = (self.current_page - 1) * self.per_page
        end_index = min(start_index + self.per_page, len(self.items))
        return self.items[start_index:end_index]

