from django import forms
from django.forms import ValidationError

class AllowedValuesField(forms.Field):
    def __init__(self, allowed_values, *args, **kwargs):
        self.allowed_values = allowed_values
        super().__init__(*args, **kwargs)

    def validate(self, value):
        if isinstance(value, list):
            invalid_values = [v for v in value if v not in self.allowed_values]
            if invalid_values:
                raise ValidationError(
                    f"The following value(s) are not allowed: {', '.join(map(str, invalid_values))}"
                )
        else:
            if value not in self.allowed_values:
                raise ValidationError("This value is not allowed")

    def clean(self, value):
        self.validate(value)
        return value

# Example usage in a Django form
class MyForm(forms.Form):
    choices = AllowedValuesField(allowed_values=["A", "B", "C"])

# Usage in a view
def my_view(request):
    if request.method == 'POST':
        form = MyForm(request.POST)
        if form.is_valid():
            # Process the form data
            pass
    else:
        form = MyForm()
    return render(request, 'my_template.html', {'form': form})
```

