class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.insert(0, item)

    def dequeue(self):
        return self.items.pop()

    def isEmpty(self):
        return len(self.items) == 0


def isCompleteBinaryTree(root):
    nonFull = False
    q = Queue()
    q.enqueue(root)

    while not q.isEmpty():
        t = q.dequeue()

        if t.getLeftChild():
            if nonFull:
                return False
            q.enqueue(t.getLeftChild())

        if t.getRightChild():
            if nonFull:
                return False
            q.enqueue(t.getRightChild())

        if t.getRightChild() is None:
            nonFull = True

    return True
```

The `isCompleteBinaryTree` function takes the root of a binary tree as input and uses a queue to perform a level order traversal of the tree. It checks if the tree satisfies the conditions of a complete binary tree and returns True if it does, and False otherwise.

