def process_table_files(pdf_extraction_dir):
    table_data = {}
    file_paths = glob.glob(os.path.join(pdf_extraction_dir, '*', 'tables', '*.table.*.csv'))

    for file_path in file_paths:
        dir_name, table_file = os.path.split(file_path)
