        returned_tuple, returned_dict = result
        if len(returned_tuple) != len(self.values):
            raise ValueError("Returned tuple length does not match the expected structure")

        if set(returned_dict.keys()) != set(self.values):
            raise ValueError("Returned dictionary keys do not match the expected structure")

        if self.meta and returned_tuple[-1] != self.meta:
            raise ValueError("Returned tuple does not contain the expected metadata")

        return result
