class CloudStorage:
    def __init__(self, capacity_bytes):
        self.capacity_bytes = capacity_bytes
        self.current_usage_bytes = 0

    def upload_file(self, file_size_bytes):
        if self.current_usage_bytes + file_size_bytes <= self.capacity_bytes:
            self.current_usage_bytes += file_size_bytes
            print(f"File of size {file_size_bytes} bytes uploaded successfully.")
        else:
            print("Insufficient space to upload the file.")

    def download_file(self, file_size_bytes):
        if file_size_bytes <= self.current_usage_bytes:
            self.current_usage_bytes -= file_size_bytes
            print(f"File of size {file_size_bytes} bytes downloaded successfully.")
        else:
            print("File size exceeds the current usage. Download failed.")

    def check_free_space(self):
        free_space = self.capacity_bytes - self.current_usage_bytes
        print(f"Available free space: {free_space} bytes")

