class FixedWidthWriter:
    def __init__(self, text, width):
        self.text = text
        self.width = width

    def format_output(self):
        # Implement the logic to format the text to fit the specified width
        # Ensure that the output is limited to 80 characters per line
        # Return the formatted text
        lines = [self.text[i:i + self.width] for i in range(0, len(self.text), self.width)]
        return '\n'.join(lines)

def FixedWidthDecorator(width):
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return FixedWidthWriter(result, width).format_output()
        return wrapper
    return decorator

@FixedWidthDecorator(80)
def format_output(text):
    return text

