```python
class Matrix:
    def __init__(self, elements):
        self.elements = elements

    def multiply(self, B):
        result = [[0 for _ in range(len(B.elements[0]))] for _ in range(len(self.elements))]
        for i in range(len(self.elements)):
            for j in range(len(B.elements[0])):
                for k in range(len(B.elements)):
                    result[i][j] += self.elements[i][k] * B.elements[k][j]
        return Matrix(result)

    def sum(self, axis):
        if axis == 0:
            result = [sum(col) for col in zip(*self.elements)]
        else:
            result = [sum(row) for row in self.elements]
        return Matrix([result])

    def A1(self):
        return self.elements[0][0]

def calculateFirstElement(matrixA, matrixB):
    return matrixA.multiply(matrixB).sum(0).A1
```

