        if self.model_index is not None:
            low_res_point = np.expand_dims(low_res_point, axis=0)
        _, indices = self.high_res_tree.query(low_res_point, k=self.k)
        if self.model_index is not None:
            indices = indices[0]
        return self.high_res_data[indices]
