def validate_params(param_types):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for i, arg in enumerate(args):
                if i < len(param_types):
                    if not isinstance(arg, param_types[i][1]):
                        raise TypeError(f"Parameter '{param_types[i][0]}' must be of type {param_types[i][1]}")
            for kwarg, value in kwargs.items():
                for param_name, param_type in param_types:
                    if kwarg == param_name and not isinstance(value, param_type):
                        raise TypeError(f"Parameter '{param_name}' must be of type {param_type}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_params([('length', int), ('width', int)])
def calculate_area(length, width):
    return length * width

print(calculate_area(5, 4))  # Output: 20
print(calculate_area(3, 'hello'))  # Output: TypeError: Parameter 'width' must be of type <class 'int'>
