from typing import List

def checkPossibility(nums: List[int]) -> bool:
    cnt = 0  # Counter for the number of modifications
    for i in range(1, len(nums)):
        if nums[i - 1] > nums[i]:
            cnt += 1
            if cnt > 1:
                return False
            if i - 2 >= 0 and nums[i - 2] > nums[i]:
                nums[i] = nums[i - 1]  # Modify the current element
            else:
                nums[i - 1] = nums[i]  # Modify the previous element
    return True
```

The `checkPossibility` function iterates through the array `nums` and counts the number of modifications needed to make the array non-decreasing. If the number of modifications exceeds 1, it returns `False`. Otherwise, it modifies the array in one move and returns `True`.

