from typing import Any, Type

def check_exception_chain(err: Exception, object_type: Type) -> bool:
    if isinstance(err, object_type):
        return True
    elif err.__cause__ is not None:
        return check_exception_chain(err.__cause__, object_type)
    elif err.__context__ is not None:
        return check_exception_chain(err.__context__, object_type)
    else:
        return False
```

The `check_exception_chain` function first checks if the current exception `err` is an instance of the `object_type` (sub-exception type) to be checked for. If it is, the function returns True. If not, it recursively checks the `__cause__` and `__context__` of the current exception until it finds the sub-exception type or exhausts the exception chain, in which case it returns False.

