import os
import random

class Mol2Sampler:
    @classmethod
    def _get_mol2files(cls, path):
        files = []
        for item in os.scandir(path):
            if item.is_file() and item.name.split(".")[-1] in ["gz", "mol2"]:
                files.append(item)
            elif item.is_dir():
                files.extend(cls._get_mol2files(item.path))
        return files

    @classmethod
    def random_sample_without_index(cls, n_samples, dir_path, verbose=True):
        sampled_files = []
        all_files = cls._get_mol2files(dir_path)
        if n_samples > len(all_files):
            raise ValueError("Number of samples exceeds the total number of files in the directory")

        sampled_files = random.sample(all_files, n_samples)
        sampled_paths = [file.path for file in sampled_files]

        if verbose:
            print(f"Sampling {n_samples} files without replacement from {dir_path}")
            print("Sampled files:")
            for path in sampled_paths:
                print(path)

        return sampled_paths
