import unicodedata

def extract_unicode_info(input_str):
    chars = []
    for c in input_str:
        c = unichr(c)
        name = unicodedata.name(c, '')
        if name.startswith("FULLWIDTH") or name.startswith("HALFWIDTH"):
            chars.append((name, c))

    unicode_info = {}
    for name, c in chars:
        p = name.split()
        if p[0] in ('HALFWIDTH', 'FULLWIDTH'):
            name = " ".join(p[1:])

        info = {
            'character': c,
            'unicode': f'U+{ord(c):04X}',
            'name': name
        }
        unicode_info[name] = info

    return unicode_info
