from typing import List, Dict, Union

def parse_field_descriptors(code_snippet: str) -> List[Dict[str, Union[str, int]]]:
    field_descriptors = []
    lines = code_snippet.split("\n")
    for line in lines:
        if "FieldDescriptor" in line:
            attributes = line.split(",")
            field = {}
            for attr in attributes:
                if "=" in attr:
                    key, value = attr.split("=")
                    key = key.strip()
                    value = value.strip().strip("'")
                    if key in ['name', 'full_name']:
                        field[key] = value
                    elif key in ['index', 'number', 'type', 'cpp_type', 'label']:
                        field[key] = int(value)
            field_descriptors.append(field)
    return field_descriptors
