        with open(file_path, 'r') as file:
            self.video_data = json.load(file)

    def get_longest_video(self):
        longest_video = max(self.video_data, key=lambda video: self._duration_to_seconds(video['duration']))
        return longest_video['title']

    def get_videos_uploaded_after(self, date_string):
        target_date = parser.isoparse(date_string)
        filtered_videos = [video['title'] for video in self.video_data if parser.isoparse(video['upload_date']) > target_date]
        return sorted(filtered_videos)

    def _duration_to_seconds(self, duration_string):
        hours, minutes, seconds = map(int, duration_string.split(':'))
        return hours * 3600 + minutes * 60 + seconds
