class DistanceCalculatorImpl(DistanceCalculator):
    def __init__(self):
        self.points = []

    def add_point(self, x, y):
        self.points.append((x, y))

    def get_distance(self, i, j):
        x1, y1 = self.points[i]
        x2, y2 = self.points[j]
        return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

    def nearest_point(self, x, y):
