def expand_macros(source_code: str) -> str:
    macros = {}
    lines = source_code.split('\n')
    expanded_code = []

    for line in lines:
        if line.startswith('#'):
            parts = line.split()
            if len(parts) == 3:
                macro_name = parts[0][1:]
                expansion = parts[2:]
                macros[macro_name] = expansion
        else:
            for macro_name in macros:
                line = line.replace(f'#{macro_name}', ' '.join(macros[macro_name]))
            expanded_code.append(line)

    return '\n'.join(expanded_code)
