def parse_bpython_string(s: str) -> List[Tuple[str, str]]:
    result = []
    i = 0
    while i < len(s):
        if s[i] == "[":
            j = s.find("]", i)
            if j != -1:
                color_code = s[i+1]
                if color_code.isalpha() and j > i+2:
                    text = s[i+2:j]
                    result.append((color_code, text))
                    i = j + 1
                else:
                    result.append(("k", s[i:j+1]))  # Default to black if color code is missing or invalid
                    i = j + 1
            else:
                result.append(("k", s[i:]))  # Default to black if closing bracket is missing
                break
        else:
            k = s.find("[", i)
            if k != -1:
                result.append(("k", s[i:k]))  # Default to black for non-colored text
                i = k
            else:
                result.append(("k", s[i:]))  # Default to black for non-colored text
                break
    return result

