        self.snapshots = {}
        self.current_snapshot_index = 0

    def take_snapshot(self, snapshot_values):
        snapshot_index = self.current_snapshot_index
        snapshot = dict(self.snapshots[snapshot_index - 1]) if snapshot_index > 0 else {}
        self.snapshots[snapshot_index] = {
            'index': snapshot_index,
            'snapshot': snapshot,
            'values': snapshot_values
        }
        self.current_snapshot_index += 1
        return snapshot_index

    def get_value(self, snapshot_index, value_node):
        if snapshot_index in self.snapshots:
            snapshot = self.snapshots[snapshot_index]['snapshot']
            if value_node in snapshot:
                return snapshot[value_node]
        return None
