import logging
from muttlib.dbconn.base import BaseClient

class DatabaseTableManager(BaseClient):
    def __init__(self, table_name, connection_params):
        super().__init__(**connection_params)
        self.table_name = table_name
        self.logger = logging.getLogger(__name__)

    def create_record(self, record):
        try:
            with self.transaction() as cursor:
                columns = ', '.join(record.keys())
                values = ', '.join('%({})s'.format(key) for key in record.keys())
                query = f"INSERT INTO {self.table_name} ({columns}) VALUES ({values})"
                cursor.execute(query, record)
                self.logger.info("Record created successfully")
        except Exception as e:
            self.logger.error(f"Error creating record: {e}")

    def read_record(self, primary_key):
        try:
            with self.transaction() as cursor:
                query = f"SELECT * FROM {self.table_name} WHERE id = %s"
                cursor.execute(query, (primary_key,))
                record = cursor.fetchone()
                if record:
                    return record
                else:
                    self.logger.info(f"No record found with primary key {primary_key}")
        except Exception as e:
            self.logger.error(f"Error reading record: {e}")

    def update_record(self, primary_key, updated_values):
        try:
            with self.transaction() as cursor:
                set_clause = ', '.join(f"{key} = %({key})s" for key in updated_values.keys())
                query = f"UPDATE {self.table_name} SET {set_clause} WHERE id = %s"
                updated_values['id'] = primary_key
                cursor.execute(query, updated_values)
                if cursor.rowcount > 0:
                    self.logger.info(f"Record with primary key {primary_key} updated successfully")
                else:
                    self.logger.info(f"No record found with primary key {primary_key}")
        except Exception as e:
            self.logger.error(f"Error updating record: {e}")

    def delete_record(self, primary_key):
        try:
            with self.transaction() as cursor:
                query = f"DELETE FROM {self.table_name} WHERE id = %s"
                cursor.execute(query, (primary_key,))
                if cursor.rowcount > 0:
                    self.logger.info(f"Record with primary key {primary_key} deleted successfully")
                else:
                    self.logger.info(f"No record found with primary key {primary_key}")
        except Exception as e:
            self.logger.error(f"Error deleting record: {e}")
