        """
        Add a key-value pair to the store. If the key already exists, update its value.
        """
        self.store[key] = value

    def get(self, key):
        """
        Retrieve the value for the given key. If the key does not exist, return None.
        """
        return self.store.get(key)

    def delete(self, key):
        """
        Delete the key-value pair for the given key. If the key does not exist, do nothing.
        """
        if key in self.store:
            del self.store[key]

    def get_all_keys(self):
        """
        Retrieve all keys in the store.
        """
        return list(self.store.keys())
