class Matcher:
    def __init__(self, pattern):
        self.pattern = pattern

    def match(self, target):
        memo = {}

        def dp(i, j):
            if (i, j) in memo:
                return memo[(i, j)]

            if j == len(self.pattern):
                return i == len(target)

            if i < len(target) and (self.pattern[j] == target[i] or self.pattern[j] == '*'):
                memo[(i, j)] = dp(i + 1, j + 1) or dp(i, j + 1)
                return memo[(i, j)]

            if self.pattern[j] == '*':
                memo[(i, j)] = dp(i, j + 1) or (i < len(target) and dp(i + 1, j))
                return memo[(i, j)]

            memo[(i, j)] = False
            return False

        return dp(0, 0)
