def find_possible_sequences(sequence, whites, reds):
    possible_sequences = []

    # Generate all possible sequences
    for i in range(10):
        for j in range(10):
            for k in range(10):
                for l in range(10):
                    possible_sequence = str(i) + str(j) + str(k) + str(l)

                    # Check if the sequence matches the feedback
                    if check_feedback(sequence, possible_sequence, whites, reds):
                        possible_sequences.append(possible_sequence)

    return possible_sequences

def check_feedback(secret, guess, whites, reds):
    secret_counts = [0] * 10
    guess_counts = [0] * 10
    white_count = 0
    red_count = 0

    for i in range(4):
        if secret[i] == guess[i]:
            red_count += 1
        else:
            secret_counts[int(secret[i])] += 1
            guess_counts[int(guess[i])] += 1

    for i in range(10):
        white_count += min(secret_counts[i], guess_counts[i])

    return white_count == whites and red_count == reds

