import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin

def scrape_by_url(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            return response.text
        else:
            return ""
    except requests.RequestException:
        return ""

def crawl_by_url(url, max_depth, visited=None, current_depth=0):
    if visited is None:
        visited = set()
    if current_depth > max_depth:
        return list(visited)
    try:
        response = requests.get(url)
        if response.status_code == 200:
            visited.add(url)
            soup = BeautifulSoup(response.text, 'html.parser')
            for link in soup.find_all('a', href=True):
                absolute_url = urljoin(url, link['href'])
                if absolute_url not in visited:
                    visited.update(crawl_by_url(absolute_url, max_depth, visited, current_depth + 1))
        return list(visited)
    except (requests.RequestException, ValueError, KeyError):
        return []

def crawl_by_keyword(keyword):
    try:
        response = requests.get("https://www.google.com/search", params={"q": keyword})
        if response.status_code == 200:
            soup = BeautifulSoup(response.text, 'html.parser')
            urls = [a['href'] for a in soup.find_all('a', href=True) if "url?q=" in a['href']]
            return [url.split("?q=")[1].split("&sa=U")[0] for url in urls]
        else:
            return []
    except requests.RequestException:
        return []
```

