    def __iter__(self):
        self.identifier = None
        self.sequence = []
        for line in self.file:
            line = line.strip()
            if line.startswith('>'):
                if self.identifier:
                    yield (self.identifier, ''.join(self.sequence))
                    self.sequence = []
                self.identifier = line[1:]
            else:
                self.sequence.append(line)
        if self.identifier:
            yield (self.identifier, ''.join(self.sequence))

    def setUp(self):
