from tensorflow.keras.callbacks import Callback

class EarlyStoppingLoss(Callback):
    def __init__(self, patience=0, verbose=False):
        super(EarlyStoppingLoss, self).__init__()
        self.patience = patience
        self.verbose = verbose
        self.wait = 0
        self.stopped_epoch = 0
        self.best = float('inf')

    def on_train_begin(self, logs=None):
        self.wait = 0
        self.stopped_epoch = 0
        self.best = float('inf')

    def on_epoch_end(self, epoch, logs=None):
        current_loss = logs.get('val_loss')
        if current_loss is None:
            raise ValueError("EarlyStoppingLoss requires val_loss available.")

        if current_loss < self.best:
            self.best = current_loss
            self.wait = 0
        else:
            self.wait += 1
            if self.wait >= self.patience:
                if self.verbose:
                    print(f"\nEpoch {epoch}: Early stopping due to no decrease in validation loss.")
                self.stopped_epoch = epoch
                self.model.stop_training = True

    def on_train_end(self, logs=None):
        if self.stopped_epoch > 0 and self.verbose:
            print(f"Epoch {self.stopped_epoch}: Early stopping, best validation loss: {self.best:.4f}")
```

This `EarlyStoppingLoss` callback class extends the Keras `Callback` class and implements the early stopping behavior based on the validation loss. It tracks the validation loss over epochs and stops the training process if the loss does not decrease for a specified number of epochs. The `on_epoch_end` method is used to monitor the validation loss and stop the training if the early stopping condition is met. The `on_train_end` method is used to print a message if the training is stopped early.

