def caesar_encrypt(plaintext, shift):
    encrypted = ""
    for char in plaintext:
        if char.isalpha():
            shift_amount = shift % 26  # Ensure the shift value wraps around the alphabet
            if char.isupper():
                encrypted += chr((ord(char) - 65 + shift_amount) % 26 + 65)
            else:
                encrypted += chr((ord(char) - 97 + shift_amount) % 26 + 97)
        else:
            encrypted += char
    return encrypted

def caesar_decrypt(encrypted_text, shift):
    decrypted = ""
    for char in encrypted_text:
        if char.isalpha():
            shift_amount = shift % 26  # Ensure the shift value wraps around the alphabet
            if char.isupper():
                decrypted += chr((ord(char) - 65 - shift_amount) % 26 + 65)
            else:
                decrypted += chr((ord(char) - 97 - shift_amount) % 26 + 97)
        else:
            decrypted += char
    return decrypted

