from typing import List, Dict

def parse_arguments(text: str) -> (List[str], Dict[str, str]):
    args = []
    kwargs = {}
    for line in text.split('\n'):
        line = line.strip()
        if line.startswith('self.parser.add_argument('):
            arguments = re.findall(r"'--?[\w-]+'", line)
            for arg in arguments:
                if arg.startswith('--'):
                    key, value = arg, None
                    match = re.search(r"help='([^']*)'", line)
                    if match:
                        value = match.group(1)
                    kwargs[key] = value
                else:
                    args.append(arg.strip("'"))
    return args, kwargs
```

