from collections import OrderedDict

class SimpleCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def add(self, key, value):
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
        self.cache[key] = value

    def get(self, key):
        if key in self.cache:
            value = self.cache[key]
            # Move the accessed key to the end to mark it as most recently used
            del self.cache[key]
            self.cache[key] = value
            return value
        return None

    def remove(self, key):
        if key in self.cache:
            del self.cache[key]
```

This solution provides a complete implementation of the `SimpleCache` class with the required methods for adding, retrieving, and removing key-value pairs from the cache. The cache is implemented using an `OrderedDict` to maintain the insertion order and efficiently handle eviction of the least recently used item when the cache reaches its maximum capacity.

