def apply_migration(operations: List[Dict[str, Union[str, Dict[str, Union[str, Any]]]]]) -> Dict[str, Any]:
    database_schema = {}  # Initialize an empty database schema
    for operation in operations:
        if operation['operation'] == 'AlterField':
            model_name = operation['model_name']
            field_name = operation['name']
            field_properties = operation['field']
            if model_name in database_schema and field_name in database_schema[model_name]:
                database_schema[model_name][field_name].update(field_properties)
            else:
                raise ValueError(f"Field '{field_name}' does not exist in model '{model_name}' for AlterField operation.")
        elif operation['operation'] == 'AddField':
            model_name = operation['model_name']
            field_name = operation['name']
            field_properties = operation['field']
            if model_name in database_schema:
                database_schema[model_name][field_name] = field_properties
            else:
                raise ValueError(f"Model '{model_name}' does not exist for AddField operation.")
        elif operation['operation'] == 'CreateModel':
            model_name = operation['model_name']
            fields = operation['fields']
            if model_name not in database_schema:
                database_schema[model_name] = {field['name']: field['field'] for field in fields}
            else:
                raise ValueError(f"Model '{model_name}' already exists for CreateModel operation.")
        else:
            raise ValueError(f"Unsupported operation: {operation['operation']}")
    return database_schema
```

The `apply_migration` function iterates through the list of alteration operations and applies each operation to the database schema. It handles AlterField, AddField, and CreateModel operations, updating the database schema accordingly. If any operation is invalid or conflicts with the current state of the database schema, the function raises a ValueError with an appropriate error message.

