def canReachEnd(arr):
    def helper(pos):
        if pos < 0 or pos >= len(arr) or pos in seen:
            return False
        if pos == len(arr) - 1:
            return True
        seen.add(pos)
        return helper(pos + arr[pos]) or helper(pos - arr[pos])

    seen = set()
    return helper(0)
```
