class Bank:
    def __init__(self):
        self.accounts = {}
        self.account_number = 1000  # Initial account number

    def create_account(self, name, initial_deposit):
        self.account_number += 1
        self.accounts[self.account_number] = {'name': name, 'balance': initial_deposit}
        return self.account_number

    def deposit(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number]['balance'] += amount
            return f"Deposit of {amount} successful. New balance: {self.accounts[account_number]['balance']}"
        else:
            return "Invalid account number"

    def withdraw(self, account_number, amount):
        if account_number in self.accounts:
            if self.accounts[account_number]['balance'] >= amount:
                self.accounts[account_number]['balance'] -= amount
                return f"Withdrawal of {amount} successful. New balance: {self.accounts[account_number]['balance']}"
            else:
                return "Insufficient funds"
        else:
            return "Invalid account number"

    def check_balance(self, account_number):
        if account_number in self.accounts:
            return f"Account balance for {self.accounts[account_number]['name']}: {self.accounts[account_number]['balance']}"
        else:
            return "Invalid account number"


# Example usage
bank = Bank()
account1 = bank.create_account("Alice", 1000)
account2 = bank.create_account("Bob", 500)
print(bank.deposit(account1, 500))  # Output: Deposit of 500 successful. New balance: 1500
print(bank.withdraw(account2, 200))  # Output: Withdrawal of 200 successful. New balance: 300
