import string

class PostError(Exception):
  def __init__(self, msg=None):
    self.msg = msg

class RegistrationCodeGenerator:
    def __init__(self):
        self.generated_codes = {}

    def generate_code(self, length: int) -> str:
        code = ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))
        while code in self.generated_codes:
            code = ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))
        self.generated_codes[code] = datetime.now()
        return code

    def validate_code(self, code: str) -> bool:
        if code in self.generated_codes:
            return True
        else:
            raise PostError("Invalid code")

    def get_time_elapsed(self, code: str) -> str:
        if code in self.generated_codes:
            elapsed_time = datetime.now() - self.generated_codes[code]
            return naturaltime(elapsed_time)
        else:
            raise PostError("Code not found")
