def process_image(image: List[List[int]]) -> float:
    """Calculate the y-coordinate of the center of mass of the processed image"""
    rows, cols = len(image), len(image[0])
    total_mass = 0
    total_y_mass = 0

    for i in range(rows):
        for j in range(cols):
            if image[i][j] != 0:
                total_mass += 1
                total_y_mass += i

