        """
        if sequence_id in self.genome_dict:
            return self.genome_dict[sequence_id]["sequence"]
        else:
            raise KeyError(f"Sequence identifier '{sequence_id}' not found in the genome")

    def get_metadata(self, sequence_id):
        """
